import { preferencesRecord, storageStateFor } from '../support/preferences';
import { openScreen, screenIds, type ScreenId } from '../support/screens';
import { expect, test } from '../support/ux-test';
import { cellState, dynamicMasks, matrixLevels, matrixThemes, requireVisualContainer, shotName } from '../support/visual';

// T037 visual regression (SC-005; TEST-STRATEGY.md 10.2). Container only, fresh stack; baselines
// are generated by the CTO in T067 (`npm run test:visual -- --update-snapshots`) and approved in T068.
requireVisualContainer();

const narrowScreens: readonly ScreenId[] = ['import', 'tracks', 'track', 'mixes', 'library'];
// The restyle dialog is taller than a full-page capture can stitch around the fixed shell (the
// stitched frames moved by the page's scroll position from run to run): capture the viewport.
const viewportScreens: readonly ScreenId[] = ['restyle-dialog'];

for (const theme of matrixThemes) {
  for (const level of matrixLevels) {
    test.describe(`${level} / ${theme}`, () => {
      test.use({ storageState: cellState(level, theme) });

      for (const screen of screenIds) {
        test(`${screen} matches its baseline`, async ({ page, uxData }) => {
          await openScreen(page, screen, uxData);
          const fullPage = !viewportScreens.includes(screen);
          await expect(page).toHaveScreenshot(shotName([screen, level, theme]), { fullPage, mask: dynamicMasks(page) });
        });
      }
    });
  }

  test.describe(`welcome / ${theme}`, () => {
    test.use({ storageState: storageStateFor(preferencesRecord({ theme, motion: 'reduced' })) });

    test('the first-run welcome panel matches its baseline', async ({ page, uxData }) => {
      await openScreen(page, 'import', uxData);
      await expect(page.getByTestId('welcome-panel')).toBeVisible();
      await expect(page).toHaveScreenshot(shotName(['welcome', theme]), { fullPage: true, mask: dynamicMasks(page) });
    });
  });

  test.describe(`help and tour / ${theme}`, () => {
    test.use({ storageState: cellState('advanced', theme) });

    test('the docked help panel on the mixer matches its baseline', async ({ page, uxData, help }) => {
      await openScreen(page, 'mixer', uxData);
      await help.open('button');
      await help.expectTopic('mixer-screen');
      await expect(page).toHaveScreenshot(shotName(['help-panel', 'mixer', theme]), { mask: dynamicMasks(page) });
    });
  });

  test.describe(`tour step / ${theme}`, () => {
    test.use({ storageState: storageStateFor(preferencesRecord({ level: 'beginner', theme, motion: 'reduced', toursDone: false })) });

    test('step 1 of the import tour matches its baseline', async ({ page, uxData, tour }) => {
      await openScreen(page, 'import', uxData);
      await tour.startFromOfferWithKeyboard('import-basics');
      await expect(tour.popover).toHaveAttribute('data-step', '1');
      await expect(page).toHaveScreenshot(shotName(['tour-step', 'import-basics', theme]), { mask: dynamicMasks(page) });
    });
  });

  test.describe(`360 px / ${theme}`, () => {
    test.use({ storageState: cellState('advanced', theme), viewport: { width: 360, height: 780 } });

    for (const screen of narrowScreens) {
      test(`${screen} at 360 px matches its baseline`, async ({ page, uxData }) => {
        await openScreen(page, screen, uxData);
        await expect(page).toHaveScreenshot(shotName([screen, '360', theme]), { fullPage: true, mask: dynamicMasks(page) });
      });
    }

    test('the help sheet at 360 px matches its baseline', async ({ page, uxData, help }) => {
      await openScreen(page, 'import', uxData);
      await help.open('button');
      await expect(page).toHaveScreenshot(shotName(['help-sheet', '360', theme]), { mask: dynamicMasks(page) });
    });
  });

  test.describe(`768 px / ${theme}`, () => {
    test.use({ storageState: cellState('advanced', theme), viewport: { width: 768, height: 1024 } });

    test('the mixer at 768 px matches its baseline', async ({ page, uxData }) => {
      await openScreen(page, 'mixer', uxData);
      await expect(page).toHaveScreenshot(shotName(['mixer', '768', theme]), { fullPage: true, mask: dynamicMasks(page) });
    });
  });
}
